def _split_path(path):
    """Split path by '/' but don't split inside {...} regex specs."""
    parts = []
    buf = []
    level = 0
    for ch in path:
        if ch == '{':
            level += 1
        elif ch == '}':
            level = max(level - 1, 0)
        if ch == '/' and level == 0:
            parts.append(''.join(buf))
            del buf[:]
        else:
